application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap');

:root {
  --ink: #172033;
  --muted: #788298;
  --line: #e8ebf2;
  --surface: #ffffff;
  --accent: #635bff;
  --accent-dark: #5048df;
  --soft: #f3f2ff;
  --green: #259b73;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  font-family: 'DM Sans', sans-serif;
  background: linear-gradient(135deg, #f6f7ff 0%, #eef8f7 100%);
}
.app-shell { width: min(100% - 32px, 680px); margin: 0 auto; padding: 72px 0 28px; }
.todo-card {
  padding: clamp(25px, 6vw, 48px);
  background: var(--surface);
  border: 1px solid rgba(255,255,255,.8);
  border-radius: 26px;
  box-shadow: 0 22px 65px rgba(46, 55, 95, .12);
}
.app-header { display: flex; align-items: center; gap: 16px; margin-bottom: 34px; }
.brand-mark { display: grid; place-items: center; width: 50px; height: 50px; color: white; font-size: 27px; font-weight: 700; background: var(--accent); border-radius: 15px; box-shadow: 0 8px 18px rgba(99,91,255,.28); }
.eyebrow { margin: 0 0 3px; color: var(--accent); font-size: 11px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
h1, h2 { font-family: 'Plus Jakarta Sans', sans-serif; }
h1 { margin: 0; font-size: clamp(25px, 5vw, 32px); letter-spacing: -.04em; }
.task-form { display: flex; gap: 10px; margin-bottom: 35px; }
.task-form input { min-width: 0; flex: 1; padding: 15px 17px; color: var(--ink); font: inherit; border: 1px solid var(--line); border-radius: 12px; outline: none; background: #fbfcfe; transition: border .2s, box-shadow .2s; }
.task-form input:focus { border-color: var(--accent); box-shadow: 0 0 0 4px rgba(99,91,255,.11); }
.task-form button { padding: 0 18px; color: white; font: 600 14px 'DM Sans', sans-serif; border: 0; border-radius: 12px; background: var(--accent); cursor: pointer; transition: background .2s, transform .2s; }
.task-form button:hover { background: var(--accent-dark); transform: translateY(-1px); }
.task-form button span { margin-left: 5px; font-size: 18px; vertical-align: -1px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; padding-bottom: 15px; border-bottom: 1px solid var(--line); }
h2 { margin: 0; font-size: 16px; letter-spacing: -.02em; }
.count-pill { padding: 6px 10px; color: var(--accent); font-size: 12px; font-weight: 600; background: var(--soft); border-radius: 20px; }
.count-pill strong { font-size: 13px; }
.task-list { display: flex; flex-direction: column; }
.task-item { display: flex; align-items: center; gap: 12px; min-height: 66px; border-bottom: 1px solid var(--line); animation: appear .25s ease-out; }
.complete-toggle { flex: 0 0 auto; width: 21px; height: 21px; padding: 0; border: 2px solid #cbd1df; border-radius: 7px; background: white; cursor: pointer; transition: .2s; }
.complete-toggle:hover { border-color: var(--accent); }
.task-item[data-completed="true"] .complete-toggle { border-color: var(--green); background: var(--green); }
.task-item[data-completed="true"] .complete-toggle::after { display: block; content: '✓'; color: white; font-size: 13px; line-height: 17px; }
.task-text { flex: 1; min-width: 0; overflow-wrap: anywhere; font-size: 15px; transition: color .2s; }
.task-item[data-completed="true"] .task-text { color: #a0a7b7; text-decoration: line-through; }
.delete-button { padding: 8px; color: #a4abbb; font-size: 18px; line-height: 1; border: 0; background: transparent; cursor: pointer; border-radius: 7px; }
.delete-button:hover { color: #e05d6f; background: #fff1f3; }
.empty-state { margin: 29px 0 8px; color: var(--muted); font-size: 14px; text-align: center; }
.empty-state[hidden] { display: none; }
.footer-note { margin: 20px 0 0; color: #8b95aa; font-size: 12px; text-align: center; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 480px) { .app-shell { padding-top: 28px; } .task-form { flex-direction: column; } .task-form button { min-height: 48px; } }

application.javascript:
(() => {
  const form = document.getElementById('task-form');
  const input = document.getElementById('task-input');
  const list = document.getElementById('task-list');
  const emptyState = document.getElementById('empty-state');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const countLabel = document.getElementById('count-label');
  let tasks = [];

  function updateSummary() {
    const incomplete = tasks.filter(task => !task.completed).length;
    count.textContent = incomplete;
    countLabel.textContent = incomplete === 1 ? 'left' : 'left';
    emptyState.hidden = tasks.length > 0;
  }

  function render() {
    list.innerHTML = '';
    tasks.forEach(task => {
      const item = document.createElement('div');
      item.className = 'task-item';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const toggle = document.createElement('button');
      toggle.className = 'complete-toggle';
      toggle.dataset.testid = 'task-complete';
      toggle.type = 'button';
      toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      toggle.setAttribute('aria-pressed', String(task.completed));
      toggle.addEventListener('click', () => {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.className = 'delete-button';
      remove.dataset.testid = 'task-delete';
      remove.type = 'button';
      remove.setAttribute('aria-label', 'Delete task');
      remove.textContent = '×';
      remove.addEventListener('click', () => {
        tasks = tasks.filter(current => current.id !== task.id);
        render();
      });

      item.append(toggle, text, remove);
      list.appendChild(item);
    });
    updateSummary();
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) return;
    tasks.push({ id: Date.now() + Math.random(), text, completed: false });
    input.value = '';
    render();
    input.focus();
  });

  render();
})();
